window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-87e5582087a2fd60"]={"versions": [{"id": "FIG-87e5582087a2fd60", "releases": ["R1.3.0", "R17-03_R1.1.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm auf Protokollebene im Kontext des Remote Event Communication Protocol (RECP). Das Diagramm visualisiert das Nachrichtenformat und den Übertragungsweg für die Statusnachricht des Rückgabewerts von Diagnosemodus $4 (Mode $4 Return Value Status Message) zwischen zwei Steuergeräten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Source Section ECU</strong>: Sendendes Steuergerät (Quellknoten), das den Status des Diagnosemodus $4 bereitstellt und versendet.</li>\n<li><strong>Destination Section ECU</strong>: Empfangendes Steuergerät (Zielknoten), an das die Statusnachricht übermittelt wird.</li>\n<li><strong>Mode $4 Return Value Status Message</strong>: Strukturierter Nachrichtenframe, aufgeteilt in:</li>\n<li>Header-Bereich (lila codiert):</li>\n<li><code>MSG_TYPE</code>: Nachrichtentyp-Identifikator (<code>TYP_MSTP</code>, Byte 0).</li>\n<li><code>CLIENT_ID</code>: Kennung des anfordernden Clients (<code>TYP_CLID</code>, Byte 1).</li>\n<li><code>RESERVED</code>: Reserviertes Feld (<code>STRCT_RESVD</code>, Bytes 2–4).</li>\n<li>Nutzdaten-Bereich (blau codiert):</li>\n<li><code>MODE4_RET</code>: Eigentlicher Rückgabewert des Modus $4 (<code>TYP_MODE4_RET</code>, Byte 5).</li>\n<li>Tail-Bereich (grün codiert):</li>\n<li><code>MSG_CTR</code>: Nachrichtenzähler zur Sequenz- und Übertragungsüberwachung (<code>TYP_MSGCTR</code>, Byte 6).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Source Section ECU</code> generiert die Statusnachricht für den Modus $4 und befüllt die Header-Felder (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), den Rückgabewert (<code>MODE4_RET</code>) sowie den zählerbasierten Nachrichtenabschluss (<code>MSG_CTR</code>).</li>\n<li>Die assemblierte Nachricht wird serialisiert und über den Kommunikationspfad von der Quell-ECU zur Ziel-ECU übertragen.</li>\n<li>Die <code>Destination Section ECU</code> empfängt die Nachricht, validiert Metadaten und Nachrichtenzähler und verarbeitet den enthaltenen Rückgabewert weiter.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Frame-Struktur definiert ein festes Datenlayout über 7 Bytes (Byte 0 bis Byte 6).</li>\n<li>Die Header-Felder dienen dem Routing und der Zuordnung der Antwort zum anfragenden Client.</li>\n<li>Das Tail-Feld <code>MSG_CTR</code> muss für Integritätsprüfungen und Erkennung von Nachrichtenverlusten ausgewertet und fortlaufend inkrementiert werden.</li>\n<li>Datenstrukturen und Typdefinitionen (insbesondere <code>TYP_MODE4_RET</code>) müssen kompatibel zu den Definitionen der Diagnostic Status Information (DSI) implementiert sein.</li>\n</ul>"}, {"id": "FIG-a1b4952cef2085fe", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm auf Protokollebene im Kontext des Remote Event Communication Protocol (RECP). Das Diagramm visualisiert das Nachrichtenformat und den Übertragungsweg für die Statusnachricht des Rückgabewerts von Diagnosemodus $4 (Mode $4 Return Value Status Message) zwischen zwei Steuergeräten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Source Section ECU</strong>: Sendendes Steuergerät (Quellknoten), das den Status des Diagnosemodus $4 bereitstellt und versendet.</li>\n<li><strong>Destination Section ECU</strong>: Empfangendes Steuergerät (Zielknoten), an das die Statusnachricht übermittelt wird.</li>\n<li><strong>Mode $4 Return Value Status Message</strong>: Strukturierter Nachrichtenframe, aufgeteilt in:</li>\n<li>Header-Bereich (lila codiert):</li>\n<li><code>MSG_TYPE</code>: Nachrichtentyp-Identifikator (<code>TYP_MSTP</code>, Byte 0).</li>\n<li><code>CLIENT_ID</code>: Kennung des anfordernden Clients (<code>TYP_CLID</code>, Byte 1).</li>\n<li><code>RESERVED</code>: Reserviertes Feld (<code>STRCT_RESVD</code>, Bytes 2–4).</li>\n<li>Nutzdaten-Bereich (blau codiert):</li>\n<li><code>MODE4_RET</code>: Eigentlicher Rückgabewert des Modus $4 (<code>TYP_MODE4_RET</code>, Byte 5).</li>\n<li>Tail-Bereich (grün codiert):</li>\n<li><code>MSG_CTR</code>: Nachrichtenzähler zur Sequenz- und Übertragungsüberwachung (<code>TYP_MSGCTR</code>, Byte 6).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Source Section ECU</code> generiert die Statusnachricht für den Modus $4 und befüllt die Header-Felder (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), den Rückgabewert (<code>MODE4_RET</code>) sowie den zählerbasierten Nachrichtenabschluss (<code>MSG_CTR</code>).</li>\n<li>Die assemblierte Nachricht wird serialisiert und über den Kommunikationspfad von der Quell-ECU zur Ziel-ECU übertragen.</li>\n<li>Die <code>Destination Section ECU</code> empfängt die Nachricht, validiert Metadaten und Nachrichtenzähler und verarbeitet den enthaltenen Rückgabewert weiter.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Frame-Struktur definiert ein festes Datenlayout über 7 Bytes (Byte 0 bis Byte 6).</li>\n<li>Die Header-Felder dienen dem Routing und der Zuordnung der Antwort zum anfragenden Client.</li>\n<li>Das Tail-Feld <code>MSG_CTR</code> muss für Integritätsprüfungen und Erkennung von Nachrichtenverlusten ausgewertet und fortlaufend inkrementiert werden.</li>\n<li>Datenstrukturen und Typdefinitionen (insbesondere <code>TYP_MODE4_RET</code>) müssen kompatibel zu den Definitionen der Diagnostic Status Information (DSI) implementiert sein.</li>\n</ul>"}], "trans": [{"from": "FIG-87e5582087a2fd60", "to": "FIG-a1b4952cef2085fe", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a1b4952cef2085fe", "to": "FIG-87e5582087a2fd60", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
